        "manglish": "Namaskaram, ithu Mrunalini Rao Couture, Jubilee Hills alle? Njan Apoorv-nu vendiyanu vilikkunnathu (calling on Apoorv's behalf). Mrunalini Rao, Founder & Creative Director-nodu oru minute samsarikkan sadhikkumo? Ningalude website mobile speed-um direct bookings-um maximize cheyyaan Apoorv thayyaraakkiya technical audit (normally ₹4,999 value ullathaanu, complimentary aayi share cheyyaam). Apoorv-umayi samsarikkan soukaryapradhamaya samayam parayamo?",
